import { forwardRef, memo, useEffect, useMemo, useRef } from 'react';

import { cn } from '../../utils';

import type { BadgeProps } from './Badge.types';

// =============================================================================
// Lookup maps — keyed by BadgeSize
// =============================================================================

const SIZE_CLASS_MAP: Readonly<Record<string, string>> = {
  sm: 'dsai-badge-sm',
  md: '',
  lg: 'dsai-badge-lg',
};

const SIZE_STYLE_MAP: Readonly<Record<string, React.CSSProperties>> = {
  sm: { fontSize: '0.65em', padding: '0.2em 0.45em' },
  md: {},
  lg: { fontSize: '0.85em', padding: '0.45em 0.85em' },
};

// =============================================================================
// Prototype-pollution-safe lookup (per CLAUDE.md security rules)
// =============================================================================

const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function safeLookup<T>(map: Readonly<Record<string, T>>, key: string, fallback: T): T {
  if (BLOCKED_KEYS.has(key)) {return fallback;}
  const value = Reflect.get(map, key) as T | undefined;
  return value !== undefined ? value : fallback;
}

// =============================================================================
// Badge Component
// =============================================================================

/**
 * Badge Component
 *
 * A Bootstrap 5 badge component for displaying labels, status indicators, and counts.
 * Supports sizes, style variants (solid/outline/subtle), dismissible badges,
 * max count truncation, visibility control, icon positioning, and animations.
 *
 * @see https://getbootstrap.com/docs/5.3/components/badge/
 */
function BadgeComponent(
  {
    children,
    variant = 'primary',
    size = 'md',
    appearance = 'solid',
    pill = false,
    dot = false,
    icon,
    iconPosition = 'start',
    className = '',
    style,
    'aria-label': ariaLabel,
    'data-testid': dataTestId,
    'data-test': dataTest,
    title,
    id,
    as: Component = 'span',
    onDismiss,
    dismissLabel = 'Remove',
    max,
    invisible = false,
    showZero = true,
    animated = false,
  }: BadgeProps,
  ref: React.ForwardedRef<HTMLSpanElement | HTMLDivElement>
): React.JSX.Element | null {
  // ---------------------------------------------------------------------------
  // showZero gate — return null before any hooks that depend on children
  // ---------------------------------------------------------------------------
  const isZeroHidden =
    !showZero && (children === 0 || children === '0');

  // ---------------------------------------------------------------------------
  // Max count truncation
  // ---------------------------------------------------------------------------
  const displayContent = useMemo(() => {
    if (isZeroHidden) {return null;}
    if (max !== undefined && typeof children === 'number' && children > max) {
      return `${max}+`;
    }
    return children;
  }, [children, max, isZeroHidden]);

  // Determine if badge has visible content
  const hasVisibleContent = useMemo(() => {
    return !!displayContent || !!icon;
  }, [displayContent, icon]);

  // ---------------------------------------------------------------------------
  // Appearance classes
  // ---------------------------------------------------------------------------
  const appearanceClasses = useMemo(() => {
    if (appearance === 'outline') {
      return `border border-${variant} text-${variant} bg-transparent`;
    }
    if (appearance === 'subtle') {
      return `bg-${variant}-subtle text-${variant}-emphasis`;
    }
    // solid (default)
    return `text-bg-${variant}`;
  }, [appearance, variant]);

  // ---------------------------------------------------------------------------
  // Size styles
  // ---------------------------------------------------------------------------
  const sizeClass = safeLookup<string>(SIZE_CLASS_MAP, size, '');
  const sizeStyle = safeLookup<React.CSSProperties>(SIZE_STYLE_MAP, size, {});

  // ---------------------------------------------------------------------------
  // Memoize class name construction
  // ---------------------------------------------------------------------------
  const bootstrapClasses = useMemo(
    () =>
      cn(
        'badge',
        appearanceClasses,
        pill && 'rounded-pill',
        sizeClass,
        invisible && 'dsai-badge-invisible',
        animated && 'dsai-badge-animated',
        className
      ),
    [appearanceClasses, pill, sizeClass, invisible, animated, className]
  );

  // ---------------------------------------------------------------------------
  // Merged styles (size + custom + invisible + animation)
  // ---------------------------------------------------------------------------
  const mergedStyle = useMemo<React.CSSProperties>(() => {
    const base: React.CSSProperties = { ...sizeStyle, ...style };
    if (invisible) {
      base.opacity = 0;
      base.pointerEvents = 'none';
    }
    return base;
  }, [sizeStyle, style, invisible]);

  // ---------------------------------------------------------------------------
  // Dev warning: dot-only badge without aria-label (fires once per mount)
  // ---------------------------------------------------------------------------
  const isDev =
    typeof process !== 'undefined' &&
    // biome-ignore lint/complexity/useLiteralKeys: noPropertyAccessFromIndexSignature requires bracket access
    (process.env?.['NODE_ENV'] === 'development' || process.env?.['NODE_ENV'] === 'test');

  useEffect(() => {
    if (isDev && dot && !hasVisibleContent && !ariaLabel) {
      console.warn(
        'Badge: Dot-only badges must have an aria-label for accessibility. ' +
          'Example: <Badge dot aria-label="Online status" />'
      );
    }
  }, [isDev, dot, hasVisibleContent, ariaLabel]);

  // ---------------------------------------------------------------------------
  // Animation: scale pulse on content change
  // ---------------------------------------------------------------------------
  const badgeRef = useRef<HTMLSpanElement | HTMLDivElement | null>(null);
  const prevContentRef = useRef<React.ReactNode>(displayContent);

  useEffect(() => {
    if (!animated || !badgeRef.current) {return;}
    if (prevContentRef.current !== displayContent) {
      const el = badgeRef.current;
      el.classList.add('dsai-badge-pulse');
      const handleEnd = (): void => {
        el.classList.remove('dsai-badge-pulse');
        el.removeEventListener('animationend', handleEnd);
      };
      el.addEventListener('animationend', handleEnd);
      prevContentRef.current = displayContent;
    }
  }, [animated, displayContent]);

  // ---------------------------------------------------------------------------
  // showZero: return null after hooks
  // ---------------------------------------------------------------------------
  if (isZeroHidden) {return null;}

  // ---------------------------------------------------------------------------
  // ARIA
  // ---------------------------------------------------------------------------
  const role = dot && !hasVisibleContent ? 'status' : undefined;
  const ariaProps = role
    ? { role, 'aria-label': ariaLabel }
    : ariaLabel
      ? { 'aria-label': ariaLabel }
      : {};

  // ---------------------------------------------------------------------------
  // Badge content assembly
  // ---------------------------------------------------------------------------
  const iconElement = icon ? (
    <span className="d-inline-flex align-items-center" aria-hidden="true">
      {icon}
    </span>
  ) : null;

  const dotElement = dot ? (
    <span
      className="d-inline-block rounded-circle"
      style={{
        width: '0.5em',
        height: '0.5em',
        backgroundColor: 'currentColor',
        ...(hasVisibleContent ? { marginRight: '0.25em' } : {}),
      }}
      aria-hidden={hasVisibleContent ? 'true' : undefined}
    />
  ) : null;

  const dismissElement = onDismiss ? (
    <button
      type="button"
      className="dsai-badge-dismiss"
      aria-label={dismissLabel}
      onClick={onDismiss}
      style={{
        background: 'none',
        border: 'none',
        color: 'inherit',
        padding: '0 0 0 0.35em',
        cursor: 'pointer',
        fontSize: 'inherit',
        lineHeight: 1,
        opacity: 0.7,
        display: 'inline-flex',
        alignItems: 'center',
      }}
    >
      ×
    </button>
  ) : null;

  const badgeContent = (
    <>
      {dotElement}
      {iconPosition === 'start' && iconElement}
      {iconElement && iconPosition === 'start' && displayContent ? (
        <span style={{ marginLeft: '0.25em' }}>{displayContent}</span>
      ) : iconElement && iconPosition === 'end' && displayContent ? (
        <span style={{ marginRight: '0.25em' }}>{displayContent}</span>
      ) : (
        displayContent
      )}
      {iconPosition === 'end' && iconElement}
      {dismissElement}
    </>
  );

  // ---------------------------------------------------------------------------
  // Ref merging (forward ref + internal animation ref)
  // ---------------------------------------------------------------------------
  const setRefs = (node: HTMLSpanElement | HTMLDivElement | null): void => {
    badgeRef.current = node;
    if (typeof ref === 'function') {
      ref(node);
    } else if (ref) {
      (ref as React.MutableRefObject<HTMLSpanElement | HTMLDivElement | null>).current = node;
    }
  };

  // ---------------------------------------------------------------------------
  // Render — unified to avoid JSX duplication
  // ---------------------------------------------------------------------------
  const sharedProps = {
    className: bootstrapClasses,
    style: mergedStyle,
    id,
    title,
    'data-testid': dataTestId,
    'data-test': dataTest,
    ...ariaProps,
  };

  if (Component === 'div') {
    return (
      <div ref={setRefs as React.Ref<HTMLDivElement>} {...sharedProps}>
        {badgeContent}
      </div>
    );
  }

  return (
    <span ref={setRefs as React.Ref<HTMLSpanElement>} {...sharedProps}>
      {badgeContent}
    </span>
  );
}

BadgeComponent.displayName = 'Badge';

const BadgeWithRef = forwardRef(BadgeComponent);
BadgeWithRef.displayName = 'Badge';

export const BadgeBase = memo(BadgeWithRef);
BadgeBase.displayName = 'Badge';

import type { ComponentSize, SafeHTMLAttributes, SemanticColorVariant } from '../../types';
import type { CSSProperties, ReactNode } from 'react';

/**
 * Badge component color variants
 * Maps to Bootstrap 5 badge background utilities (text-bg-*)
 * @see SemanticColorVariant
 */
export type BadgeVariant = SemanticColorVariant;

/**
 * Badge size
 * Maps to Bootstrap-compatible font-size and padding scales
 */
export type BadgeSize = ComponentSize;

/**
 * Badge visual appearance / style treatment
 * - `solid` — filled background with contrasting text (default, Bootstrap text-bg-*)
 * - `outline` — transparent background with colored border and text
 * - `subtle` — light tinted background with darker text (Bootstrap bg-*-subtle)
 */
export type BadgeAppearance = 'solid' | 'outline' | 'subtle';

/**
 * Badge placement when used inside Badge.Wrapper
 */
export type BadgePlacement = 'top-end' | 'top-start' | 'bottom-end' | 'bottom-start';

/**
 * Badge overlap shape — adjusts offset for the anchor element's shape
 */
export type BadgeOverlap = 'rectangular' | 'circular';

/**
 * Safe HTML attributes for Badge component
 * Whitelists allowed HTML attributes to prevent unrestricted prop spreading
 * Blocks dangerous attributes like 'onclick', 'onchange', etc.
 * @see SafeHTMLAttributes
 */
export type SafeBadgeHTMLAttributes = SafeHTMLAttributes<HTMLSpanElement>;

/**
 * Badge component props
 *
 * @see https://getbootstrap.com/docs/5.3/components/badge/
 *
 * @example
 * ```tsx
 * // Basic badge
 * <Badge variant="primary">New</Badge>
 *
 * // Sized badge
 * <Badge variant="success" size="lg">Active</Badge>
 *
 * // Outline badge
 * <Badge variant="danger" appearance="outline">Alert</Badge>
 *
 * // Dismissible badge
 * <Badge variant="primary" onDismiss={() => remove(id)}>React</Badge>
 *
 * // Auto-truncated count
 * <Badge variant="danger" max={99}>{150}</Badge>  // renders "99+"
 *
 * // Badge wrapper (overlay on another element)
 * <Badge.Wrapper>
 *   <MailIcon />
 *   <Badge variant="danger" pill>4</Badge>
 * </Badge.Wrapper>
 * ```
 */
export interface BadgeProps extends SafeBadgeHTMLAttributes {
  /**
   * Badge content
   */
  children?: ReactNode;

  /**
   * Badge color variant
   * @default 'primary'
   */
  variant?: BadgeVariant;

  /**
   * Badge size
   * @default 'md'
   */
  size?: BadgeSize;

  /**
   * Visual appearance / style treatment
   * @default 'solid'
   */
  appearance?: BadgeAppearance;

  /**
   * Pill shape (fully rounded)
   * @default false
   */
  pill?: boolean;

  /**
   * Show dot indicator instead of/before content
   * Useful for status indicators
   * NOTE: Requires aria-label when used without visible text
   * @default false
   */
  dot?: boolean;

  /**
   * Icon to display alongside badge text
   * Will be hidden from screen readers (aria-hidden="true")
   */
  icon?: ReactNode;

  /**
   * Icon position relative to text content
   * @default 'start'
   */
  iconPosition?: 'start' | 'end';

  /**
   * Element to render as
   * @default 'span'
   */
  as?: 'span' | 'div';

  /**
   * Callback fired when the dismiss button is clicked.
   * When provided, a close button is rendered inside the badge.
   */
  onDismiss?: () => void;

  /**
   * Accessible label for the dismiss button
   * @default 'Remove'
   */
  dismissLabel?: string;

  /**
   * Maximum numeric value to display.
   * When children is a number exceeding max, displays "{max}+".
   * Only applies when children is a number.
   */
  max?: number;

  /**
   * If true, the badge is hidden visually (opacity 0, pointer-events none)
   * but remains in the DOM to preserve layout.
   * @default false
   */
  invisible?: boolean;

  /**
   * If false and children is the number 0, the badge is not rendered.
   * @default true
   */
  showZero?: boolean;

  /**
   * Enable mount and content-change animations
   * @default false
   */
  animated?: boolean;
}

/**
 * Badge.Wrapper props — positions a badge as an overlay on a child element
 */
export interface BadgeWrapperProps {
  /** The anchor element and badge element */
  children: ReactNode;

  /**
   * Badge placement relative to the anchor
   * @default 'top-end'
   */
  placement?: BadgePlacement;

  /**
   * Shape of the anchor element — adjusts badge offset
   * @default 'rectangular'
   */
  overlap?: BadgeOverlap;

  /** Additional CSS class */
  className?: string;

  /** Inline styles */
  style?: CSSProperties;
}

import { forwardRef, memo, useMemo } from 'react';

import { cn } from '../../utils';

import type { BadgeWrapperProps } from './Badge.types';

// =============================================================================
// Placement CSS mapping
// =============================================================================

const PLACEMENT_STYLES: Readonly<Record<string, React.CSSProperties>> = {
  'top-end': { top: 0, right: 0, transform: 'translate(50%, -50%)' },
  'top-start': { top: 0, left: 0, transform: 'translate(-50%, -50%)' },
  'bottom-end': { bottom: 0, right: 0, transform: 'translate(50%, 50%)' },
  'bottom-start': { bottom: 0, left: 0, transform: 'translate(-50%, 50%)' },
};

const CIRCULAR_OFFSET: Readonly<Record<string, React.CSSProperties>> = {
  'top-end': { top: '14%', right: '14%', transform: 'translate(50%, -50%)' },
  'top-start': { top: '14%', left: '14%', transform: 'translate(-50%, -50%)' },
  'bottom-end': { bottom: '14%', right: '14%', transform: 'translate(50%, 50%)' },
  'bottom-start': { bottom: '14%', left: '14%', transform: 'translate(-50%, 50%)' },
};

const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function safeLookup<T>(map: Readonly<Record<string, T>>, key: string, fallback: T): T {
  if (BLOCKED_KEYS.has(key)) {return fallback;}
  const value = Reflect.get(map, key) as T | undefined;
  return value !== undefined ? value : fallback;
}

// =============================================================================
// BadgeWrapper Component
// =============================================================================

/**
 * Badge.Wrapper — positions a badge as an overlay on a child element.
 *
 * @example
 * ```tsx
 * <Badge.Wrapper>
 *   <MailIcon />
 *   <Badge variant="danger" pill>4</Badge>
 * </Badge.Wrapper>
 *
 * <Badge.Wrapper placement="bottom-start" overlap="circular">
 *   <Avatar name="John" />
 *   <Badge variant="success" dot aria-label="Online" />
 * </Badge.Wrapper>
 * ```
 */
function BadgeWrapperComponent(
  {
    children,
    placement = 'top-end',
    overlap = 'rectangular',
    className,
    style,
  }: BadgeWrapperProps,
  ref: React.ForwardedRef<HTMLDivElement>
): React.JSX.Element {
  const offsetMap = overlap === 'circular' ? CIRCULAR_OFFSET : PLACEMENT_STYLES;
  const placementStyle = safeLookup<React.CSSProperties>(offsetMap, placement, {});

  const wrapperClasses = useMemo(
    () => cn('dsai-badge-wrapper', 'd-inline-flex', 'position-relative', className),
    [className]
  );

  return (
    <div
      ref={ref}
      className={wrapperClasses}
      style={style}
      data-placement={placement}
      data-overlap={overlap}
    >
      {/* Render children, injecting position styles onto badge children */}
      {Array.isArray(children)
        ? children.map((child, index) => {
            // The last child is assumed to be the badge; overlay it
            if (
              index === children.length - 1 &&
              child &&
              typeof child === 'object' &&
              'props' in child
            ) {
              const childStyle = {
                position: 'absolute' as const,
                zIndex: 1,
                ...placementStyle,
                ...(typeof child.props?.style === 'object' ? child.props.style : {}),
              };
              // Use cloneElement-free approach: wrap in a positioned span
              return (
                <span key={index} className="dsai-badge-wrapper-badge" style={childStyle}>
                  {child}
                </span>
              );
            }
            return child;
          })
        : children}
    </div>
  );
}

BadgeWrapperComponent.displayName = 'BadgeWrapper';

const BadgeWrapperWithRef = forwardRef(BadgeWrapperComponent);
BadgeWrapperWithRef.displayName = 'BadgeWrapper';

export const BadgeWrapper = memo(BadgeWrapperWithRef);
BadgeWrapper.displayName = 'BadgeWrapper';

import { BadgeBase } from './Badge';
import { BadgeWrapper } from './BadgeWrapper';

/**
 * Badge compound component with Wrapper sub-component.
 *
 * @example
 * ```tsx
 * <Badge variant="primary">New</Badge>
 *
 * <Badge.Wrapper>
 *   <MailIcon />
 *   <Badge variant="danger" pill>4</Badge>
 * </Badge.Wrapper>
 * ```
 */
export const Badge = Object.assign(BadgeBase, {
  Wrapper: BadgeWrapper,
});

export { BadgeWrapper } from './BadgeWrapper';
export type {
  BadgeAppearance,
  BadgeOverlap,
  BadgePlacement,
  BadgeProps,
  BadgeSize,
  BadgeVariant,
  BadgeWrapperProps,
} from './Badge.types';
